WITH warehouse_credit AS ( SELECT w.w_warehouse_name, cd.cd_credit_rating, cd.cd_marital_status, SUM(ws.ws_net_profit) AS total_net_profit, SUM(ws.ws_sales_price * ws.ws_quantity) AS total_sales, AVG(ws.ws_ext_discount_amt) AS avg_discount, COUNT(DISTINCT ws.ws_order_number) AS order_cnt, COUNT(DISTINCT ws.ws_promo_sk) AS promo_cnt, AVG(p.p_cost) AS avg_promo_cost, SUM(cd.cd_purchase_estimate) AS total_purchase_estimate FROM web_sales ws JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk JOIN customer_demographics cd ON ws.ws_bill_cdemo_sk = cd.cd_demo_sk LEFT JOIN promotion p ON ws.ws_promo_sk = p.p_promo_sk GROUP BY w.w_warehouse_name, cd.cd_credit_rating, cd.cd_marital_status ) SELECT w_warehouse_name, cd_credit_rating, CASE cd_marital_status WHEN 'M' THEN 'Married' WHEN 'S' THEN 'Single' ELSE cd_marital_status END AS marital_status_desc, total_sales, ROUND(100.0 * total_sales / SUM(total_sales) OVER (PARTITION BY w_warehouse_name), 2) AS sales_pct_of_warehouse, total_net_profit, avg_discount, avg_promo_cost, total_purchase_estimate, DENSE_RANK() OVER (PARTITION BY w_warehouse_name ORDER BY total_net_profit DESC) AS profit_rank_within_warehouse, RANK() OVER (ORDER BY total_purchase_estimate DESC) AS purchase_estimate_global_rank FROM warehouse_credit ORDER BY w_warehouse_name, profit_rank_within_warehouse
